// ================== Janamoon - مغز ربات (همه‌ی منطق اینجاست) ==================
// این کد دقیقاً همون منطقیه که توی پیش‌نمایش HTML با داده‌ی واقعی تست شده.
// ورودی: آپدیت خام تلگرام (از نود Telegram Trigger) + botToken (از نود Config)
// خروجی: یک آیتم به‌ازای هر پیامی که باید به تلگرام فرستاده بشه

const update = $input.first().json;
const BOT_TOKEN = update.botToken;

// ---------------- دیتابیس شهرها ----------------
// city, airport name (optional), extra search keys, intl(true/false)
const RAW = [
  ['تهران', 'مهرآباد', ['tehran', 'thr', 'mehrabad'], false],
  ['تهران', 'امام خمینی', ['tehran', 'ika', 'imam', 'امام'], false],
  ['مشهد', 'شهید هاشمی‌نژاد', ['mashhad', 'mhd'], false],
  ['شیراز', 'شهید دستغیب', ['shiraz', 'syz'], false],
  ['اصفهان', 'شهید بهشتی', ['isfahan', 'esfahan', 'ifn'], false],
  ['تبریز', 'شهید مدنی', ['tabriz', 'tbz'], false],
  ['کیش', '', ['kish', 'kih'], false],
  ['اهواز', '', ['ahvaz', 'awz'], false],
  ['بندرعباس', '', ['bandarabbas', 'bnd'], false],
  ['قشم', '', ['qeshm', 'gsm'], false],
  ['رشت', '', ['rasht', 'ras'], false],
  ['ساری', '', ['sari', 'sry'], false],
  ['کرمان', '', ['kerman', 'ker'], false],
  ['یزد', '', ['yazd', 'azd'], false],
  ['ارومیه', '', ['urmia', 'omh'], false],
  ['کرمانشاه', '', ['kermanshah', 'ksh'], false],
  ['زاهدان', '', ['zahedan', 'zah'], false],
  ['بوشهر', '', ['bushehr', 'buz'], false],
  ['اردبیل', '', ['ardabil', 'adu'], false],
  ['استانبول', 'فرودگاه استانبول', ['istanbul', 'ist'], true],
  ['استانبول', 'صبیحه گوکچن', ['istanbul', 'saw', 'sabiha'], true],
  ['آنکارا', '', ['ankara', 'esb'], true],
  ['آنتالیا', '', ['antalya', 'ayt'], true],
  ['دبی', '', ['dubai', 'dxb'], true],
  ['شارجه', '', ['sharjah', 'shj'], true],
  ['مسقط', '', ['muscat', 'mct'], true],
  ['دوحه', '', ['doha', 'doh'], true],
  ['مسکو', '', ['moscow', 'svo'], true],
  ['باکو', '', ['baku', 'gyd'], true],
  ['تفلیس', '', ['tbilisi', 'tbs'], true],
  ['ایروان', '', ['yerevan', 'evn'], true],
  ['نجف', '', ['najaf', 'njf'], true],
  ['بغداد', '', ['baghdad', 'bgw'], true],
  ['اربیل', '', ['erbil', 'ebl'], true],
  ['کابل', '', ['kabul', 'kbl'], true],
  ['بانکوک', '', ['bangkok', 'bkk'], true],
  ['کوالالامپور', '', ['kualalumpur', 'kul'], true],
];
const QUICK = ['تهران', 'مشهد', 'شیراز', 'اصفهان', 'تبریز', 'کیش'];
const QUICK_INTL = ['استانبول', 'دبی', 'مسکو', 'باکو', 'تفلیس', 'ایروان'];
const QUICK_ORIGIN_INTL = ['تهران', 'مشهد', 'استانبول', 'دبی', 'مسکو', 'باکو'];

function norm(s) {
  return String(s).toLowerCase()
    .replace(/[ً-ٟـ]/g, '')
    .replace(/[يى]/g, 'ی').replace(/ك/g, 'ک')
    .replace(/[أإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ؤ/g, 'و')
    .replace(/[‌‍\s\-_.]/g, '');
}
function lev(a, b) {
  const m = a.length, n = b.length;
  if (!m) return n;
  if (!n) return m;
  let prev = [];
  for (let j = 0; j <= n; j++) prev[j] = j;
  for (let i = 1; i <= m; i++) {
    const cur = [i];
    for (let j = 1; j <= n; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[n];
}
const cityCount = {};
RAW.forEach(function (r) { cityCount[r[0]] = (cityCount[r[0]] || 0) + 1; });
const AIRPORTS = RAW.map(function (r) {
  const city = r[0], name = r[1];
  const keys = [norm(city)];
  if (name) { keys.push(norm(name)); keys.push(norm(city + name)); }
  r[2].forEach(function (x) { keys.push(norm(x)); });
  return { city: city, keys: keys, intl: r[3] === true };
});
function isIntlCity(city) {
  const a = AIRPORTS.find(function (x) { return x.city === city; });
  return !!(a && a.intl);
}
function score(q, keys) {
  let best = 99;
  keys.forEach(function (s) {
    if (s === q) best = Math.min(best, 0);
    else if (s.startsWith(q)) best = Math.min(best, 1);
    else if (s.includes(q)) best = Math.min(best, 2);
    else if (q.length >= 3) {
      const maxD = q.length >= 6 ? 2 : 1;
      const d = Math.min(lev(q, s.slice(0, q.length)), lev(q, s));
      if (d <= maxD) best = Math.min(best, 3 + d);
    }
  });
  return best;
}
// خروجی: لیست اسم شهرهای منحصربه‌فرد (بدون تفکیک فرودگاه، برای سادگی دکمه‌های تلگرام)
function searchCities(text, session) {
  const q = norm(text);
  if (!q) return [];
  const scored = [];
  AIRPORTS.forEach(function (a, i) { const sc = score(q, a.keys); if (sc < 99) scored.push({ a: a, sc: sc, i: i }); });
  scored.sort(function (x, y) { return x.sc - y.sc || x.i - y.i; });
  const seen = {};
  const out = [];
  for (const s of scored) {
    if (session.tripType === 'domestic' && s.a.intl) continue;
    if (seen[s.a.city]) continue;
    seen[s.a.city] = true;
    out.push(s.a.city);
    if (out.length >= 5) break;
  }
  return out;
}

// ---------------- کد فرودگاه‌ها ----------------
const CODES = {
  'تهران': 'THR', 'مشهد': 'MHD', 'شیراز': 'SYZ', 'اصفهان': 'IFN', 'تبریز': 'TBZ', 'کیش': 'KIH',
  'اهواز': 'AWZ', 'بندرعباس': 'BND', 'قشم': 'GSM', 'رشت': 'RAS', 'ساری': 'SRY', 'کرمان': 'KER',
  'یزد': 'AZD', 'ارومیه': 'OMH', 'کرمانشاه': 'KSH', 'زاهدان': 'ZAH', 'بوشهر': 'BUZ', 'اردبیل': 'ADU',
};
const INTL_CODES = {
  'استانبول': 'IST', 'آنکارا': 'ESB', 'آنتالیا': 'AYT', 'دبی': 'DXB', 'شارجه': 'SHJ',
  'مسقط': 'MCT', 'دوحه': 'DOH', 'مسکو': 'SVO', 'باکو': 'GYD', 'تفلیس': 'TBS',
  'ایروان': 'EVN', 'نجف': 'NJF', 'بغداد': 'BGW', 'اربیل': 'EBL', 'کابل': 'KBL',
  'بانکوک': 'BKK', 'کوالالامپور': 'KUL',
};
function flightCityCode(city, tripType) {
  if (isIntlCity(city)) return INTL_CODES[city] || null;
  if (city === 'تهران' && tripType === 'international') return 'IKA'; // پروازهای خارجی فقط از امام‌خمینی
  return CODES[city] || null;
}

// ---------------- تاریخ واقعی (شمسی + میلادی) ----------------
function tehranNow() {
  return new Date(new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Tehran' }).replace(' ', 'T') + 'Z');
}
function targetDates() {
  const now = tehranNow();
  const start = new Date(now);
  if (now.getUTCHours() >= 21) start.setUTCDate(start.getUTCDate() + 1);
  start.setUTCHours(12, 0, 0, 0);
  const out = [];
  for (let i = 0; i < 3; i++) {
    const d = new Date(start);
    d.setUTCDate(d.getUTCDate() + i);
    const iso = d.toISOString().slice(0, 10);
    const p = new Intl.DateTimeFormat('en-US-u-ca-persian-nu-latn', { timeZone: 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(d);
    const g = t => p.find(x => x.type === t).value;
    const shamsi = `${g('year')}-${g('month')}-${g('day')}`;
    const label = new Intl.DateTimeFormat('fa-IR-u-ca-persian', { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long' }).format(d);
    out.push({ iso, shamsi, label });
  }
  return out;
}
function toAbsoluteMs(depStr) {
  return depStr.indexOf('+') >= 0 ? new Date(depStr).getTime() : new Date(depStr + '+03:30').getTime();
}
function pickWinner(candidates) {
  const valid = candidates.filter(function (x) { return !!x; });
  if (!valid.length) return null;
  valid.sort(function (x, y) { return (x.toman - y.toman) || (y.seats - x.seats); });
  return valid[0];
}
const faDigits = s => String(s).replace(/\d/g, d => '۰۱۲۳۴۵۶۷۸۹'[d]);
const fmtToman = n => Math.round(n).toLocaleString('fa-IR').replace(/٬/g, '،');

// ---------------- درخواست به سه سایت (دقیقاً همون endpointهای تست‌شده) ----------------
async function fetchAlibaba(origin, dest) {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://ws.alibaba.ir/api/v2/flights/domestic/available/cheapest',
    headers: { 'Content-Type': 'application/json' },
    body: { origin, destination: dest, backwardDay: 0, forwardDay: 5, referenceDate: new Date().toISOString() },
    json: true,
  });
  return (data && data.result) || [];
}
function alibabaForDate(items, day, origin, dest) {
  const row = items.find(r => r.departureDateTime && r.departureDateTime.slice(0, 10) === day.iso);
  if (!row || !row.adultPrice) return null;
  return {
    toman: row.adultPrice / 10, dep: row.departureDateTime, arr: row.arrivalTime, seats: row.capacity,
    link: `https://www.alibaba.ir/flights/${origin}-${dest}?adult=1&child=0&infant=0&departing=${day.shamsi}`,
  };
}
async function fetchFlytodayForDate(origin, dest, day, isDomestic) {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://www.flytoday.ir/api/gateway/v1/Flight/SplittedSearch?sortBy=Cheapest&pageNumber=1&pageSize=25',
    headers: { 'Content-Type': 'application/json' },
    body: {
      adultCount: 1, childCount: 0, infantCount: 0, isJalali: true,
      originDestinationInformations: [{ departureDateTime: day.iso, destinationLocationCode: dest, destinationType: 'City', originLocationCode: origin, originType: 'City' }],
      pricingSourceType: 0,
      travelPreference: { cabinType: 'Y', maxStopsQuantity: 'All', airTripType: 'OneWay' },
    },
    json: true,
  });
  const items = (data && data.pricedItineraries) || [];
  if (!items.length) return null;
  let cheapest = items[0];
  for (const it of items) {
    if (it.airItineraryPricingInfo.itinTotalFare.totalFare < cheapest.airItineraryPricingInfo.itinTotalFare.totalFare) cheapest = it;
  }
  const seg = cheapest.originDestinationOptions[0].flightSegments[0];
  return {
    toman: cheapest.airItineraryPricingInfo.itinTotalFare.totalFare / 10,
    dep: seg.departureDateTime,
    arr: seg.arrivalDateTime,
    seats: seg.seatsRemaining,
    link: `https://www.flytoday.ir/flight/search?departure=${origin.toLowerCase()},1&arrival=${dest.toLowerCase()},1&departureDate=${day.iso}&adt=1&chd=0&inf=0&cabin=1&isDomestic=${isDomestic === false ? 'false' : 'true'}&isAnyWhere=false`,
  };
}
async function fetchMrbilitForDate(origin, dest, day) {
  const data = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://flight.atighgasht.com/api/Flights',
    headers: { 'Content-Type': 'application/json' },
    body: {
      AdultCount: 1, ChildCount: 0, InfantCount: 0, CabinClass: 'All', Baggage: true,
      IncludeFlightsWithHigherCapacity: true,
      Routes: [{ OriginCode: origin, DestinationCode: dest, DepartureDate: day.iso }],
    },
    json: true,
  });
  const flights = (data && data.Flights) || [];
  let best = null;
  flights.forEach(function (f) {
    const leg = f.Segments && f.Segments[0] && f.Segments[0].Legs && f.Segments[0].Legs[0];
    if (!leg || leg.FlightStatus !== 'Ok') return;
    (f.Prices || []).forEach(function (p) {
      const adl = (p.PassengerFares || []).filter(function (x) { return x.PaxType === 'ADL'; })[0];
      if (!adl) return;
      if (!best || adl.TotalFare < best.rial) best = { rial: adl.TotalFare, dep: leg.DepartureTime, arr: leg.ArrivalTime, seats: p.Capacity };
    });
  });
  if (!best) return null;
  return {
    toman: best.rial / 10, dep: best.dep, arr: best.arr, seats: best.seats,
    link: 'https://mrbilit.com/flights/' + origin + '-' + dest + '?departureDate=' + day.shamsi,
  };
}

// علی‌بابا و مستربلیط فقط برای داخلی قابل‌اعتمادن؛ خارجی فقط فلای‌تودی
async function liveResultMessages(session) {
  const isIntlTrip = session.tripType === 'international';
  const origin = flightCityCode(session.origin.city, session.tripType);
  const dest = flightCityCode(session.dest.city, session.tripType);
  const originLabel = session.origin.city, destLabel = session.dest.city;

  if (!origin || !dest) {
    return [
      { text: '<b>' + originLabel + ' ← ' + destLabel + '</b>\nبرای این مسیر هنوز به سایت‌ها وصل نشدیم.' },
      { text: 'برای جست‌وجوی دیگه از دکمه زیر استفاده کن.', keyboard: [[{ text: 'جستجوی جدید', callback_data: 'search' }]] },
    ];
  }

  const days = targetDates();
  const minDeparture = tehranNow().getTime() + 2 * 3600 * 1000;

  let alibabaItems = [];
  let alibabaFailed = true;
  if (!isIntlTrip) {
    alibabaFailed = false;
    try { alibabaItems = await fetchAlibaba.call(this, origin, dest); } catch (e) { alibabaFailed = true; }
  }

  const flytodayResults = [];
  for (const day of days) {
    try { flytodayResults.push(await fetchFlytodayForDate.call(this, origin, dest, day, !isIntlTrip)); }
    catch (e) { flytodayResults.push('error'); }
  }

  let mrbilitResults = days.map(() => 'error');
  if (!isIntlTrip) {
    mrbilitResults = [];
    for (const day of days) {
      try { mrbilitResults.push(await fetchMrbilitForDate.call(this, origin, dest, day)); }
      catch (e) { mrbilitResults.push('error'); }
    }
  }

  const winners = days.map(function (day, i) {
    const a = alibabaFailed ? null : alibabaForDate(alibabaItems, day, origin, dest);
    const fRaw = flytodayResults[i];
    const f = fRaw === 'error' ? null : fRaw;
    const mRaw = mrbilitResults[i];
    const m = mRaw === 'error' ? null : mRaw;
    let w = pickWinner([a, f, m]);
    if (w && toAbsoluteMs(w.dep) < minDeparture) w = null;
    const allFailed = alibabaFailed && fRaw === 'error' && mRaw === 'error';
    return { day, winner: w, bothFailed: allFailed };
  });

  const validToman = winners.filter(x => x.winner).map(x => x.winner.toman);
  const globalCheapest = validToman.length ? Math.min.apply(null, validToman) : null;

  const out = [{ text: '<b>' + originLabel + ' ← ' + destLabel + '</b>\nارزون‌ترین بلیط هر روز در ۳ روز آینده (داده‌ی زنده):' }];
  winners.forEach(function (x) {
    if (x.bothFailed) {
      out.push({ text: '🔴 <b>' + x.day.label + '</b>\nدریافت قیمت با مشکل مواجه شد، دوباره امتحان کن.' });
      return;
    }
    if (!x.winner) {
      out.push({ text: '🔴 <b>' + x.day.label + '</b>\nپروازی پیدا نشد.' });
      return;
    }
    const dep = faDigits(x.winner.dep.slice(11, 16));
    const arr = faDigits(x.winner.arr.slice(11, 16));
    const tag = x.winner.toman === globalCheapest ? ' (ارزون‌ترین)' : '';
    const msg = { text: '🟢 <b>' + x.day.label + '</b>\nساعت ' + dep + ' تا ' + arr + '\n<b>' + fmtToman(x.winner.toman) + ' تومان</b>' + tag };
    if (x.winner.link) msg.keyboard = [[{ text: 'لینک خرید', url: x.winner.link }]];
    out.push(msg);
  });
  out.push({ text: 'قیمت‌ها برای هر بزرگسال است و ممکن است هر لحظه تغییر کند.', keyboard: [[{ text: 'جستجوی جدید', callback_data: 'search' }]] });
  return out;
}

function quickCityButtons(session, excludeCity) {
  let list;
  if (session.tripType === 'international') {
    list = session.step === 'dest'
      ? (session.origin && !isIntlCity(session.origin.city) ? QUICK_INTL : QUICK)
      : QUICK_ORIGIN_INTL;
  } else {
    list = QUICK;
  }
  list = list.filter(c => c !== excludeCity);
  const act = session.step === 'dest' ? 'd' : 'o';
  const rows = [];
  for (let i = 0; i < list.length; i += 2) {
    rows.push(list.slice(i, i + 2).map(c => ({ text: c, callback_data: act + ':' + c })));
  }
  return rows;
}

const WELCOME_TEXT =
  'سلام، به <b>Janamoon ✈️</b> خوش اومدی.\n\n' +
  'من ارزون‌ترین بلیط هواپیما را برای ۳ روز آینده در مسیری که بگی پیدا میکنم و لینک خرید را برات میفرستم.\n\n' +
  'من بلیط نمیفروشم، فقط قیمت‌ها را مقایسه میکنم و تو را به سایت فروش میفرستم.\n\n' +
  'برای شروع، دکمه‌ی زیر را بزن!';
const HELP_TEXT =
  'راهنما:\n۱. مبدأ و مقصد را انتخاب کن یا اسمشان را بنویس.\n۲. من ارزون‌ترین بلیط ۳ روز آینده را پیدا می‌کنم.\n' +
  '۳. با دکمه‌ی لینک، به سایت فروش می‌روی و خودت خرید می‌کنی.\n\nقبل از ساعت ۲۱ روز جاری هم حساب می‌شود؛ بعد از آن جستجو از فردا شروع می‌شود.';
const START_KB = [[{ text: 'جستجوی ارزون‌ترین پرواز', callback_data: 'search' }], [{ text: 'راهنما', callback_data: 'help' }]];

// ================== شروع پردازش آپدیت ==================
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};

const isCallback = !!update.callback_query;
const isMessage = !!update.message;

if (!isCallback && !isMessage) return []; // آپدیت‌های ناشناخته (edited_message و ...) نادیده گرفته میشن

const chatId = isCallback ? update.callback_query.message.chat.id : update.message.chat.id;
const text = isMessage && typeof update.message.text === 'string' ? update.message.text : null;
const callbackData = isCallback ? update.callback_query.data : null;

// جواب دادن به callback_query تا اسپینر روی دکمه قطع بشه (fire and forget)
if (isCallback) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${BOT_TOKEN}/answerCallbackQuery`,
      body: { callback_query_id: update.callback_query.id },
      json: true,
    });
  } catch (e) { /* بی‌اهمیت */ }
}

let session = staticData.sessions[chatId] || { step: null, origin: null, dest: null, tripType: null };

let action = null, value = null;
if (!isCallback && text && text.trim() === '/start') {
  action = 'start';
} else if (isCallback) {
  const idx = callbackData.indexOf(':');
  const act = idx === -1 ? callbackData : callbackData.slice(0, idx);
  const val = idx === -1 ? null : callbackData.slice(idx + 1);
  if (act === 'search' || act === 'new') action = 'search';
  else if (act === 't') { action = 'triptype'; value = val === 'i' ? 'international' : 'domestic'; }
  else if (act === 'o') { action = 'origin'; value = val; }
  else if (act === 'd') { action = 'dest'; value = val; }
  else if (act === 'help') action = 'help';
  else if (act === 'nolink') action = 'nolink';
} else if (isMessage && text) {
  action = 'typed'; value = text;
} else {
  return []; // پیام غیرمتنی (عکس، استیکر و ...) رو نادیده می‌گیریم
}

const messages = []; // { text, keyboard? }

if (action === 'start') {
  session = { step: null, origin: null, dest: null, tripType: null };
  messages.push({ text: WELCOME_TEXT, keyboard: START_KB });
} else if (action === 'search') {
  session = { step: 'triptype', origin: null, dest: null, tripType: null };
  messages.push({ text: 'پرواز داخلی می‌خوای یا خارجی؟', keyboard: [[{ text: 'داخلی', callback_data: 't:d' }, { text: 'خارجی', callback_data: 't:i' }]] });
} else if (action === 'triptype') {
  session.tripType = value;
  session.step = 'origin';
  messages.push({ text: 'مبدأ را انتخاب کن، یا اسم شهر یا فرودگاه را بنویس:', keyboard: quickCityButtons(session, null) });
} else if (action === 'origin') {
  session.origin = { city: value };
  session.step = 'dest';
  messages.push({ text: 'مبدأ: <b>' + value + '</b>\nحالا مقصد را انتخاب کن، یا اسمش را بنویس:', keyboard: quickCityButtons(session, value) });
} else if (action === 'dest') {
  if (session.origin && value === session.origin.city) {
    messages.push({ text: 'مبدأ و مقصد نمی‌توانند یکی باشند. مقصد دیگری انتخاب کن یا بنویس:', keyboard: quickCityButtons(session, value) });
  } else {
    session.dest = { city: value };
    session.step = null;
    const days0 = targetDates();
    messages.push({ text: 'در حال جستجوی زنده برای ۳ روز آینده (' + days0[0].label + ' تا ' + days0[2].label + ')...' });
    const results = await liveResultMessages.call(this, session);
    messages.push(...results);
  }
} else if (action === 'help') {
  messages.push({ text: HELP_TEXT, keyboard: [[{ text: 'جستجوی ارزون‌ترین پرواز', callback_data: 'search' }]] });
} else if (action === 'nolink') {
  messages.push({ text: 'لینک پروازهای این مسیر هنوز مشخص نشده است.' });
} else if (action === 'typed') {
  if (session.step === 'origin' || session.step === 'dest') {
    const found = searchCities(value, session);
    if (found.length) {
      const act = session.step === 'dest' ? 'd' : 'o';
      messages.push({ text: 'این‌ها را پیدا کردم. یکی را انتخاب کن:', keyboard: found.map(c => [{ text: c, callback_data: act + ':' + c }]) });
    } else {
      messages.push({ text: 'چیزی پیدا نکردم. اسم شهر یا فرودگاه را دوباره بنویس، یا از دکمه‌ها انتخاب کن:', keyboard: quickCityButtons(session, session.origin ? session.origin.city : null) });
    }
  } else {
    messages.push({ text: 'برای شروع، دکمه‌ی زیر را بزن.', keyboard: [[{ text: 'جستجوی ارزون‌ترین پرواز', callback_data: 'search' }]] });
  }
}

staticData.sessions[chatId] = session;

return messages.map(function (m) {
  const body = { chat_id: chatId, text: m.text, parse_mode: 'HTML' };
  if (m.keyboard) body.reply_markup = { inline_keyboard: m.keyboard };
  return { json: { botToken: BOT_TOKEN, body: body } };
});
